    16	/** Puts the inn's pieces together and runs the HTTP server. */
    17	public final class Hotel {
    18	
    19	    private final Javalin server;
    20	
    21	    public Hotel(DataSource dataSource) {
    22	        Rooms rooms = new Rooms(dataSource);
    23	        ReservationStore store = new ReservationStore(dataSource);
    24	        SentMessages sentMessages = new SentMessages(dataSource);
    25	        RatePlans ratePlans = new RatePlans();
