     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final RatePlans ratePlans;
    18	    private final EmailSender emailSender;
    19	
    20	    public ReservationService(Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    21	            RatePlans ratePlans, EmailSender emailSender) {
    22	        this.rooms = rooms;
    23	        this.store = store;
    24	        this.priceCalculator = priceCalculator;
    25	        this.ratePlans = ratePlans;
    26	        this.emailSender = emailSender;
    27	    }
    28	
    29	    public synchronized Reservation create(NewReservation request) {
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    32	        }
    33	        if (request.guests() < 1) {
    34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    35	        }
    36	        Room room = rooms.find(request.roomNumber())
    37	                .orElseThrow(() -> new HotelException(
    38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    39	        if (request.guests() > room.capacity()) {
    40	            throw new HotelException(
    41	                    ErrorCode.CAPACITY_EXCEEDED,
    42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    43	        }
    44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        Price price = priceCalculator.calculate(room, request);
    49	        return store.add(request, price);
    50	    }
    51	
    52	    public Reservation find(long reservationId) {
    53	        return store.find(reservationId)
    54	                .orElseThrow(() -> new HotelException(
    55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    56	    }
    57	
    58	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    59	    public synchronized Reservation confirm(long reservationId) {
    60	        Reservation reservation = find(reservationId);
    61	        if (reservation.status() != ReservationStatus.PENDING) {
    62	            throw notAllowed(reservation, "confirm");
    63	        }
    64	        reservation.confirmPayment();
    65	        store.update(reservation);
    66	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    67	        emailSender.send(
    68	                reservation.guest().email(),
    69	                "Reserva confirmada - " + HOTEL_NAME,
    70	                confirmationEmailBody(reservation, receipt));
    71	        return reservation;
    72	    }
    73	
    74	    /**
    75	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    76	     * reservation was never paid, so nothing comes back).
    77	     */
    78	    public synchronized Reservation cancel(long reservationId) {
    79	        Reservation reservation = find(reservationId);
    80	        if (reservation.status() != ReservationStatus.PENDING
    81	                && reservation.status() != ReservationStatus.CONFIRMED) {
    82	            throw notAllowed(reservation, "cancel");
    83	        }
    84	        BigDecimal refund = ratePlans.policyFor(reservation.ratePlan()).refund(reservation);
    85	        reservation.cancel(refund);
    86	        store.update(reservation);
    87	        return reservation;
    88	    }
    89	
    90	    public synchronized Reservation checkIn(long reservationId) {
    91	        Reservation reservation = find(reservationId);
    92	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    93	            throw notAllowed(reservation, "check in");
    94	        }
    95	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    96	        store.update(reservation);
    97	        return reservation;
    98	    }
    99	
   100	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   101	    public synchronized ReservationReceipt checkOut(long reservationId) {
   102	        Reservation reservation = find(reservationId);
   103	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   104	            throw notAllowed(reservation, "check out");
   105	        }
   106	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   107	        store.update(reservation);
   108	        return new ReservationReceipt(reservation, roomOf(reservation));
   109	    }
   110	
   111	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   112	    public ReservationReceipt receiptCopy(long reservationId) {
   113	        Reservation reservation = find(reservationId);
   114	        if (!reservation.isPaid()) {
   115	            throw notAllowed(reservation, "issue a receipt for");
   116	        }
   117	        return new ReservationReceipt(reservation, roomOf(reservation));
   118	    }
   119	
   120	    private Room roomOf(Reservation reservation) {
   121	        return rooms.find(reservation.roomNumber()).orElseThrow();
   122	    }
   123	
   124	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   125	        return "Olá, " + reservation.guest().name() + "!\n\n"
   126	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   127	                + receipt.text() + "\n"
   128	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   129	                + "Até breve!\n";
   130	    }
   131	
   132	    private static HotelException notAllowed(Reservation reservation, String operation) {
   133	        return new HotelException(
   134	                ErrorCode.OPERATION_NOT_ALLOWED,
   135	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   136	    }
   137	}
