  8	import hotel.messages.SentMessages;
  9	import hotel.rooms.Rooms;
 10	import java.math.BigDecimal;
 11	import java.time.LocalDate;
 12	import org.junit.jupiter.api.AfterEach;
 13	import org.junit.jupiter.api.Test;
 14	
 15	class NewRatePlansTest {
 16	
 17	    private final EmptyDatabase database = new EmptyDatabase();
 18	    private final RatePlans ratePlans = new RatePlans();
 19	    private final ReservationService service = new ReservationService(new Rooms(database.dataSource()),
 20	            new ReservationStore(database.dataSource()), new PriceCalculator(ratePlans), ratePlans,
 21	            new EmailSender(new SentMessages(database.dataSource())));
 22	
 23	    @AfterEach
 24	    void closeDatabase() {
 25	        database.close();
 26	    }
 27	
 28	    private Reservation book(int room, String checkIn, String checkOut, RatePlan plan, String companyCode) {
 29	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
 30	        return service.create(new NewReservation(
 31	                room, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), 1, plan, companyCode));
 32	    }
 33	
 34	    @Test
 35	    void corporateUsesTheCompanyDiscount() {
 36	        Reservation reservation = book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "TECNOSUL");
 37	
 38	        assertEquals(new BigDecimal("93.58"), reservation.price().discount());
 39	        assertEquals(new BigDecimal("686.22"), reservation.price().total());
 40	    }
 41	
 42	    @Test
 43	    void corporateNeedsAKnownCompany() {
 44	        assertThrows(HotelException.class, () -> book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, null));
 45	        assertThrows(HotelException.class, () -> book(201, "2027-03-10", "2027-03-12", RatePlan.CORPORATE, "ACME"));
 46	    }
 47	
 48	    @Test
 49	    void theWeekendPackageIsAFixedPriceFromFridayToSunday() {
 50	        Reservation reservation = book(201, "2027-03-12", "2027-03-14", RatePlan.WEEKEND_PACKAGE, null);
 51	        assertEquals(new BigDecimal("820.00"), reservation.price().total());
 52	        service.confirm(reservation.id());
 53	
 54	        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
 55	        assertThrows(HotelException.class, () -> book(202, "2027-03-13", "2027-03-15", RatePlan.WEEKEND_PACKAGE, null));
 56	    }
 57	
 58	    @Test
 59	    void theLongStayNeedsSevenNights() {
 60	        Reservation reservation = book(101, "2027-03-01", "2027-03-08", RatePlan.LONG_STAY, null);
 61	
 62	        assertEquals(new BigDecimal("174.93"), reservation.price().discount());
 63	        assertEquals(new BigDecimal("1574.37"), reservation.price().total());
 64	        assertThrows(HotelException.class, () -> book(102, "2027-03-01", "2027-03-07", RatePlan.LONG_STAY, null));
 65	    }
 66	}
