 72	
 73	import hotel.rooms.Room;
 74	import hotel.rooms.RoomType;
 75	import java.math.BigDecimal;
 76	import java.time.LocalDate;
 77	import org.junit.jupiter.api.Test;
 78	
 79	class PriceCalculatorTest {
 80	
 81	    private final PriceCalculator calculator = new PriceCalculator(new RatePlans());
 82	    private final Room standardRoom = new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90"));
 83	    private final Room suite = new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90"));
 84	
 85	    private Price price(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
 86	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
 87	        return calculator.calculate(room, new NewReservation(room.number(), guest, checkIn, checkOut, 1, plan, null));
 88	    }
 89	
 90	    @Test
 91	    void lowSeasonNightsCostTheNightlyRate() {
 92	        Price price = price(
 93	                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 13), RatePlan.STANDARD);
 94	
 95	        assertEquals(3, price.nights());
 96	        assertEquals(new BigDecimal("749.70"), price.subtotal());
 97	        assertEquals(new BigDecimal("0.00"), price.discount());
 98	        assertEquals(new BigDecimal("749.70"), price.total());
 99	    }
100	
101	    @Test
102	    void highSeasonStartsOnDecember15() {
103	        Price price = price(
104	                standardRoom, LocalDate.of(2027, 12, 14), LocalDate.of(2027, 12, 16), RatePlan.STANDARD);
105	
106	        // December 14: 249.90; December 15: 249.90 + 20% = 299.88
107	        assertEquals(new BigDecimal("549.78"), price.total());
108	    }
109	
110	    @Test
111	    void highSeasonEndsWithFebruary() {
112	        Price price = price(
113	                standardRoom, LocalDate.of(2028, 2, 29), LocalDate.of(2028, 3, 2), RatePlan.STANDARD);
114	
115	        // February 29 (leap year): 299.88; March 1: 249.90
116	        assertEquals(new BigDecimal("549.78"), price.total());
117	    }
118	
119	    @Test
120	    void julyIsHighSeason() {
121	        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 6, 30)));
122	        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 1)));
123	        assertTrue(PriceCalculator.isHighSeason(LocalDate.of(2027, 7, 31)));
124	        assertFalse(PriceCalculator.isHighSeason(LocalDate.of(2027, 8, 1)));
125	    }
126	
127	    @Test
128	    void nonRefundableTakes15PercentOffRoundingHalfEven() {
129	        Price price = price(
130	                standardRoom, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 11), RatePlan.NON_REFUNDABLE);
131	
132	        // 15% of 249.90 = 37.485, which rounds half-even to 37.48 (half-up would give 37.49)
133	        assertEquals(new BigDecimal("37.48"), price.discount());
134	        assertEquals(new BigDecimal("212.42"), price.total());
135	    }
136	
137	    @Test
138	    void nonRefundableDiscountIsOnTheHighSeasonPrice() {
139	        Price price = price(
140	                suite, LocalDate.of(2027, 1, 5), LocalDate.of(2027, 1, 9), RatePlan.NON_REFUNDABLE);
141	
142	        // 4 nights of 579.90 + 20% = 695.88 each
143	        assertEquals(new BigDecimal("2783.52"), price.subtotal());
144	        assertEquals(new BigDecimal("417.53"), price.discount());
145	        assertEquals(new BigDecimal("2365.99"), price.total());
146	    }
147	}

