271	    @Test
272	    void servesTheReportsAsCsv() throws Exception {
273	        long id = json.readTree(post("/reservations", RESERVATION_JSON).body()).get("id").asLong();
274	        post("/reservations/" + id + "/confirmation", "");
275	
276	        HttpResponse<String> occupancy = get("/reports/occupancy?date=2027-07-11");
277	        assertEquals(200, occupancy.statusCode());
278	        assertTrue(occupancy.headers().firstValue("Content-Type").orElse("").startsWith("text/csv"));
279	        assertTrue(occupancy.body().endsWith("total,1/5\n"));
