281	        assertTrue(get("/reports/revenue?month=2027-07").body().endsWith("total,935.76\n"));
282	        assertEquals(400, get("/reports/revenue?month=july").statusCode());
283	        assertEquals(400, get("/reports/occupancy").statusCode());
284	    }
