182	class HttpApiTest {
183	
184	    private static final String RESERVATION_JSON = """
185	            {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
186	             "guestCpf": "111.222.333-44", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
187	             "guests": 2, "ratePlan": "STANDARD"}
188	            """;
189	
190	    private final HttpClient client = HttpClient.newHttpClient();
191	    private final ObjectMapper json = new ObjectMapper();
