208	    private HttpResponse<String> get(String path) throws IOException, InterruptedException {
209	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path)).GET().build(),
210	                HttpResponse.BodyHandlers.ofString());
211	    }
212	
213	    private HttpResponse<String> post(String path, String body) throws IOException, InterruptedException {
214	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path))
215	                        .header("Content-Type", "application/json")
216	                        .POST(HttpRequest.BodyPublishers.ofString(body))
217	                        .build(),
218	                HttpResponse.BodyHandlers.ofString());
219	    }
220	
221	    @Test
222	    void listsTheRooms() throws Exception {
223	        HttpResponse<String> response = get("/rooms");
224	
225	        assertEquals(200, response.statusCode());
226	        JsonNode rooms = json.readTree(response.body());
227	        assertEquals(5, rooms.size());
228	        assertEquals(101, rooms.get(0).get("number").asInt());
229	        assertEquals("249.9", rooms.get(0).get("nightlyRate").asText());
230	    }
231	
232	    @Test
233	    void booksConfirmsAndChecksOut() throws Exception {
234	        HttpResponse<String> created = post("/reservations", RESERVATION_JSON);
235	        assertEquals(201, created.statusCode());
236	        JsonNode reservation = json.readTree(created.body());
237	        long id = reservation.get("id").asLong();
238	        assertEquals("PENDING", reservation.get("status").asText());
239	        assertEquals("2027-07-10", reservation.get("checkIn").asText());
240	        assertEquals(935.76, reservation.get("total").asDouble());
241	
242	        assertEquals(200, post("/reservations/" + id + "/confirmation", "").statusCode());
243	        JsonNode messages = json.readTree(get("/messages").body());
244	        assertEquals(1, messages.size());
245	        assertEquals("carla@example.com", messages.get(0).get("to").asText());
246	
247	        assertEquals(200, post("/reservations/" + id + "/check-in", "").statusCode());
248	        HttpResponse<String> checkedOut = post("/reservations/" + id + "/check-out", "");
249	        assertEquals(200, checkedOut.statusCode());
250	        assertEquals("Comprovante de reserva", json.readTree(checkedOut.body()).get("title").asText());
251	        assertEquals("CHECKED_OUT", json.readTree(get("/reservations/" + id).body()).get("status").asText());
252	    }
